"use strict";
// Published theory only; no exercise answers or grading data. Generated by scripts/build_nouns_rule.py.
const NOUNS_RULE_CONTENT = "<div class=\"mv nr\" id=\"nr-root\" lang=\"ru\">\n\n<header class=\"mv-hero\" id=\"карта-раздела\">\n  <h1>Nouns</h1>\n  <p>Существительные: исчисляемые и нет, множественное число, принадлежность, артикли и определители. Главное собрано в таблицы и карточки; исключения и редкие случаи раскрываются по нажатию.</p>\n  <div class=\"mv-chips\">\n    <span class=\"mv-chip\">countable / uncountable</span><span class=\"mv-chip\">plural</span><span class=\"mv-chip\">a piece of</span>\n    <span class=\"mv-chip\">’s / of</span><span class=\"mv-chip\">compound nouns</span><span class=\"mv-chip\">a / the / —</span><span class=\"mv-chip\">many / much</span>\n  </div>\n  <div class=\"mv-pair nr-demo\">\n    <div><h4>Можно посчитать</h4><span class=\"mv-ex\"><span class=\"mv-m\">a book</span>, <span class=\"mv-m\">three books</span></span></div>\n    <div><h4>Нельзя посчитать</h4><span class=\"mv-ex\"><span class=\"mv-m\">some advice</span>, <span class=\"mv-m\">a piece of</span> advice</span></div>\n  </div>\n</header>\n\n<nav class=\"mv-nav\" aria-label=\"Разделы правила\">\n  <a href=\"#nr-1\">1 Типы</a><a href=\"#nr-2\">2 Партитивы</a><a href=\"#nr-3\">3 Два значения</a><a href=\"#nr-4\">4 Мн. число</a><a href=\"#nr-5\">5 Особые формы</a>\n  <a href=\"#nr-6\">6 ’s и of</a><a href=\"#nr-7\">7 Составные</a><a href=\"#nr-8\">8 Группы</a><a href=\"#nr-9\">9 Артикли</a><a href=\"#nr-10\">10 many / much</a><a href=\"#nr-11\">11 Проверка</a>\n</nav>\n\n<!-- 1 -->\n<section class=\"mv-sec\" id=\"nr-1\">\n  <span id=\"исчисляемые-и-неисчисляемые-существительные\"></span>\n  <h2><span class=\"mv-num\">1</span>Исчисляемое или нет?</h2>\n  <p class=\"mv-lead\">Первый вопрос к любому существительному. От него зависят a/an, -s, числа и many/much.</p>\n  <div class=\"mv-scroll\"><table class=\"mv-table\">\n    <thead><tr><th>Признак</th><th>Countable</th><th>Uncountable</th></tr></thead>\n    <tbody>\n      <tr><td>a / an</td><td><span class=\"mv-ok\">a book</span></td><td><span class=\"mv-x\">an advice</span> → a piece of advice</td></tr>\n      <tr><td>Множественное число</td><td>book → <span class=\"mv-m\">books</span></td><td><span class=\"mv-x\">advices</span>: формы нет</td></tr>\n      <tr><td>Числа</td><td>three books</td><td><span class=\"mv-x\">three advices</span> → three pieces of advice</td></tr>\n      <tr><td>Количество</td><td><span class=\"mv-tag mv-t-ab\">many · few · fewer</span></td><td><span class=\"mv-tag mv-t-ad\">much · little · less</span></td></tr>\n      <tr><td>Глагол</td><td>The books <span class=\"mv-m\">are</span> here.</td><td>The news <span class=\"mv-m\">is</span> here.</td></tr>\n    </tbody>\n  </table></div>\n  <h3 class=\"nr-h3\">Проверьте слово</h3>\n  <p class=\"nr-sub\">Нажмите на слово — увидите, как с ним работать.</p>\n  <div class=\"nr-words\" role=\"group\" aria-label=\"Слова для проверки\">\n    <button type=\"button\" data-k=\"c\" data-ok=\"a book · two books · many books\" data-bad=\"much books\">book</button>\n    <button type=\"button\" data-k=\"c\" data-ok=\"an idea · ideas · few ideas\" data-bad=\"a little idea\">idea</button>\n    <button type=\"button\" data-k=\"u\" data-ok=\"some advice · a piece of advice · much advice\" data-bad=\"an advice · advices\">advice</button>\n    <button type=\"button\" data-k=\"u\" data-ok=\"some news · a piece of news · The news is good.\" data-bad=\"a news · The news are good.\">news</button>\n    <button type=\"button\" data-k=\"u\" data-ok=\"some information · two pieces of information\" data-bad=\"informations · two informations\">information</button>\n    <button type=\"button\" data-k=\"u\" data-ok=\"some furniture · a piece of furniture\" data-bad=\"furnitures · a furniture\">furniture</button>\n    <button type=\"button\" data-k=\"u\" data-ok=\"luggage · a suitcase · two bags of luggage\" data-bad=\"luggages · a luggage\">luggage</button>\n    <button type=\"button\" data-k=\"u\" data-ok=\"money · little money · a coin / a note\" data-bad=\"moneys · a money\">money</button>\n    <button type=\"button\" data-k=\"u\" data-ok=\"homework · a piece of homework\" data-bad=\"homeworks · a homework\">homework</button>\n    <button type=\"button\" data-k=\"u\" data-ok=\"weather · nice weather · What awful weather!\" data-bad=\"a weather · weathers\">weather</button>\n    <button type=\"button\" data-k=\"c\" data-ok=\"a job · two jobs\" data-bad=\"a work (работа)\">job</button>\n    <button type=\"button\" data-k=\"u\" data-ok=\"work · a lot of work\" data-bad=\"works (работа) · a work\">work</button>\n  </div>\n  <div class=\"nr-verdict\" aria-live=\"polite\" hidden></div>\n  <div class=\"mv-note mv-warn\"><b>Русский подсказывает неверно.</b> Совет, новость, мебель, багаж, информация, деньги в русском — обычные слова, а в английском — «масса»: <span class=\"mv-x\">an advice</span>, <span class=\"mv-x\">two informations</span>, <span class=\"mv-x\">a furniture</span>.</div>\n  <details class=\"nr-more\">\n    <summary>Какие слова неисчисляемые</summary>\n    <div class=\"mv-scroll\"><table class=\"mv-table\">\n      <thead><tr><th>Группа</th><th>Примеры</th></tr></thead>\n      <tbody>\n        <tr><td>Вещества, материалы</td><td>water, milk, bread, rice, sugar, salt, cheese, butter, oil, air, sand, gold, wood, paper, glass, iron</td></tr>\n        <tr><td>Абстрактные понятия</td><td>advice, information, knowledge, news, progress, research, work, homework, help, luck, music, health, fun</td></tr>\n        <tr><td>Состояния, явления</td><td>weather, traffic, money, time, space, electricity, pollution, rubbish</td></tr>\n        <tr><td>Собирательные «массы»</td><td>furniture, luggage, baggage, equipment, jewellery, machinery, clothing, scenery, cutlery, mail</td></tr>\n        <tr><td>Науки и деятельность</td><td>mathematics, physics, economics, politics, athletics, gymnastics</td></tr>\n      </tbody>\n    </table></div>\n  </details>\n</section>\n\n<!-- 2 -->\n<section class=\"mv-sec\" id=\"nr-2\">\n  <span id=\"как-посчитать-неисчисляемое-партитивы\"></span>\n  <h2><span class=\"mv-num\">2</span>Как посчитать неисчисляемое</h2>\n  <p class=\"mv-lead\">Считаем не саму «массу», а порцию, упаковку или кусок. Счёт и -s переходят на партитив.</p>\n  <div class=\"mv-grid\">\n    <div class=\"mv-card\"><b class=\"mv-ic\">💡</b><h4>Абстрактное</h4><p><span class=\"mv-m\">a piece of</span> · a bit of · an item of</p><span class=\"mv-ex\">a piece of advice, news, furniture</span></div>\n    <div class=\"mv-card\"><b class=\"mv-ic\">☕</b><h4>Напитки</h4><p><span class=\"mv-m\">a cup / glass / bottle / can of</span></p><span class=\"mv-ex\">a cup of tea, a glass of water</span></div>\n    <div class=\"mv-card\"><b class=\"mv-ic\">🍞</b><h4>Еда</h4><p><span class=\"mv-m\">a loaf / slice / bar / bowl of</span></p><span class=\"mv-ex\">a loaf of bread, a bar of chocolate</span></div>\n    <div class=\"mv-card\"><b class=\"mv-ic\">📦</b><h4>Упаковка</h4><p><span class=\"mv-m\">a carton / jar / tin / packet / bag of</span></p><span class=\"mv-ex\">a jar of honey, a tin of soup</span></div>\n    <div class=\"mv-card\"><b class=\"mv-ic\">🧂</b><h4>Малая доза</h4><p><span class=\"mv-m\">a drop / grain / pinch of</span></p><span class=\"mv-ex\">a pinch of salt, a drop of rain</span></div>\n    <div class=\"mv-card\"><b class=\"mv-ic\">👖</b><h4>Парные вещи</h4><p><span class=\"mv-m\">a pair of</span></p><span class=\"mv-ex\">a pair of scissors, two pairs of jeans</span></div>\n  </div>\n  <div class=\"mv-note\">Число — на партитиве, существительное после <span class=\"mv-m\">of</span> остаётся без -s: <span class=\"mv-ok\">three pieces of advice</span>, <span class=\"mv-ok\">two cups of coffee</span>, <span class=\"mv-x\">three piece of advices</span>.</div>\n  <details class=\"nr-more\">\n    <summary>Полная таблица партитивов</summary>\n    <div class=\"mv-scroll\"><table class=\"mv-table\">\n      <thead><tr><th>Что считаем</th><th>Партитив</th><th>Примеры</th></tr></thead>\n      <tbody>\n        <tr><td>Абстрактное и «массы»</td><td>a piece of · a bit of (разг.) · an item of</td><td>a piece of advice, a bit of luck, an item of clothing</td></tr>\n        <tr><td>Хлеб, торт</td><td>a loaf of · a slice of · a piece of</td><td>a loaf of bread, a slice of bread, a piece of cake</td></tr>\n        <tr><td>Напитки</td><td>a cup / glass / bottle / can of</td><td>a cup of tea, a glass of water, a bottle of milk, a can of cola</td></tr>\n        <tr><td>Упаковка</td><td>a carton / jar / tin / packet / bag of</td><td>a carton of juice, a jar of honey, a tin of soup, a packet of rice, a bag of sugar</td></tr>\n        <tr><td>Плитка, тюбик</td><td>a bar of · a tube of</td><td>a bar of chocolate, a bar of soap, a tube of toothpaste</td></tr>\n        <tr><td>Посуда</td><td>a bowl of · a spoonful of</td><td>a bowl of soup, a spoonful of sugar</td></tr>\n        <tr><td>Малая доза</td><td>a drop of · a grain of · a pinch of</td><td>a drop of rain, a grain of rice, a pinch of salt</td></tr>\n        <tr><td>Лист</td><td>a sheet of</td><td>a sheet of paper</td></tr>\n        <tr><td>Парные предметы</td><td>a pair of</td><td>a pair of scissors, a pair of jeans</td></tr>\n      </tbody>\n    </table></div>\n    <p class=\"nr-p\">Партитивы бывают и с исчисляемыми во мн. ч.: a bag of apples, a bunch of grapes, a packet of crisps, a kilo of potatoes.</p>\n    <div class=\"mv-note\">Партитив закреплён за словом: <span class=\"mv-ok\">a loaf of bread</span>, но <span class=\"mv-ok\">a bar of chocolate</span>. Для абстрактных слов универсален <span class=\"mv-m\">a piece of</span>: <span class=\"mv-x\">a loaf of advice</span>. В заказе допустимо коротко: <i>Two coffees, please</i> — две порции.</div>\n  </details>\n</section>\n\n<!-- 3 -->\n<section class=\"mv-sec\" id=\"nr-3\">\n  <span id=\"слова-с-двумя-значениями-исчисляемое-неисчисляемое\"></span>\n  <h2><span class=\"mv-num\">3</span>Одно слово — два значения</h2>\n  <p class=\"mv-lead\">Материал или абстракция — неисчисляемое. Предмет, порция или вид — исчисляемое.</p>\n  <div class=\"mv-scroll\"><table class=\"mv-table\">\n    <thead><tr><th>Слово</th><th><span class=\"mv-tag mv-t-ad\">Uncountable</span> масса</th><th><span class=\"mv-tag mv-t-ab\">Countable</span> предмет, порция</th></tr></thead>\n    <tbody>\n      <tr><td>glass</td><td>made of glass — стекло</td><td>a glass — стакан; glasses — очки</td></tr>\n      <tr><td>paper</td><td>a sheet of paper — бумага</td><td>a paper — газета, доклад; papers — документы</td></tr>\n      <tr><td>hair</td><td>long hair — волосы</td><td>a hair — один волос</td></tr>\n      <tr><td>room</td><td>There is no room. — место</td><td>a room — комната</td></tr>\n      <tr><td>time</td><td>no time — время</td><td>a time — раз; times — эпоха</td></tr>\n      <tr><td>experience</td><td>a lot of experience — опыт</td><td>an experience — случай, событие</td></tr>\n      <tr><td>coffee, tea</td><td>I drink coffee. — напиток</td><td>Two coffees, please. — порции</td></tr>\n      <tr><td>chicken</td><td>We had chicken. — мясо</td><td>a chicken — живая курица</td></tr>\n    </tbody>\n  </table></div>\n  <details class=\"nr-more\">\n    <summary>Ещё слова с двумя значениями</summary>\n    <div class=\"mv-scroll\"><table class=\"mv-table\">\n      <thead><tr><th>Слово</th><th>Неисчисляемое</th><th>Исчисляемое</th></tr></thead>\n      <tbody>\n        <tr><td>iron</td><td>металл</td><td>an iron — утюг</td></tr>\n        <tr><td>wood</td><td>древесина</td><td>a wood / woods — лес</td></tr>\n        <tr><td>light</td><td>свет</td><td>a light — лампа, огонь; lights — светофор</td></tr>\n        <tr><td>work</td><td>работа, труд</td><td>a work — произведение; works — завод</td></tr>\n        <tr><td>business</td><td>дело, торговля</td><td>a business — предприятие</td></tr>\n        <tr><td>fish</td><td>рыба как еда</td><td>a fish — рыба; fishes — виды рыб</td></tr>\n        <tr><td>cheese, wine</td><td>продукт</td><td>a cheese, French wines — сорта</td></tr>\n        <tr><td>chocolate</td><td>шоколад</td><td>a chocolate — конфета</td></tr>\n        <tr><td>noise</td><td>шум вообще</td><td>a noise — отдельный звук</td></tr>\n      </tbody>\n    </table></div>\n    <div class=\"mv-note\">Проверка: речь о материале, веществе, абстракции — без a/an и -s. Об отдельном предмете, порции, виде — с a/an и -s: <i>I drink coffee every day. Two coffees, please.</i></div>\n  </details>\n</section>\n\n<!-- 4 -->\n<section class=\"mv-sec\" id=\"nr-4\">\n  <span id=\"регулярное-образование-множественного-числа\"></span>\n  <h2><span class=\"mv-num\">4</span>Множественное число: как образовать</h2>\n  <p class=\"mv-lead\">Смотрим на конец слова. В большинстве случаев хватает пяти правил.</p>\n  <div class=\"mv-scroll\"><table class=\"mv-table\">\n    <thead><tr><th>Конец слова</th><th>Что делаем</th><th>Примеры</th></tr></thead>\n    <tbody>\n      <tr><td>обычное слово</td><td><span class=\"mv-tag mv-t-ab\">+ s</span></td><td>book → books, chair → chairs</td></tr>\n      <tr><td>-s, -ss, -sh, -ch, -x, -z</td><td><span class=\"mv-tag mv-t-ad\">+ es</span></td><td>bus → buses, dish → dishes, watch → watches, box → boxes</td></tr>\n      <tr><td>согласная + y</td><td><span class=\"mv-tag mv-t-du\">y → ies</span></td><td>city → cities, baby → babies</td></tr>\n      <tr><td>гласная + y</td><td><span class=\"mv-tag mv-t-ab\">+ s</span></td><td>day → days, boy → boys, key → keys</td></tr>\n      <tr><td>согласная + o</td><td><span class=\"mv-tag mv-t-ad\">+ es</span> (частые)</td><td>tomato → tomatoes, potato → potatoes, hero → heroes</td></tr>\n      <tr><td>гласная + o, сокращения</td><td><span class=\"mv-tag mv-t-ab\">+ s</span></td><td>radio → radios, zoo → zoos, photo → photos, piano → pianos</td></tr>\n      <tr><td>-f / -fe</td><td><span class=\"mv-tag mv-t-pr\">f → ves</span></td><td>knife → knives, leaf → leaves, life → lives, shelf → shelves</td></tr>\n      <tr><td>-z после одной гласной</td><td><span class=\"mv-tag mv-t-of\">zz + es</span></td><td>quiz → quizzes</td></tr>\n      <tr><td>имена, сокращения, цифры</td><td><span class=\"mv-tag mv-t-ab\">+ s</span></td><td>two Marys, MPs, CDs, the 1990s</td></tr>\n    </tbody>\n  </table></div>\n  <h3 class=\"nr-h3\">Выберите форму</h3>\n  <div class=\"nr-quiz\" data-title=\"plural\">\n    <div class=\"nr-q\"><span class=\"nr-qs\">one party → two …</span><div class=\"nr-opts\"><button type=\"button\">partys</button><button type=\"button\" data-ok=\"1\">parties</button><button type=\"button\">partyes</button></div></div>\n    <div class=\"nr-q\"><span class=\"nr-qs\">one wife → two …</span><div class=\"nr-opts\"><button type=\"button\">wifes</button><button type=\"button\" data-ok=\"1\">wives</button><button type=\"button\">wifies</button></div></div>\n    <div class=\"nr-q\"><span class=\"nr-qs\">one boy → two …</span><div class=\"nr-opts\"><button type=\"button\" data-ok=\"1\">boys</button><button type=\"button\">boies</button><button type=\"button\">boyes</button></div></div>\n    <div class=\"nr-q\"><span class=\"nr-qs\">one quiz → two …</span><div class=\"nr-opts\"><button type=\"button\">quizes</button><button type=\"button\">quizs</button><button type=\"button\" data-ok=\"1\">quizzes</button></div></div>\n  </div>\n  <details class=\"nr-more\">\n    <summary>Исключения: -o, -f и другие</summary>\n    <div class=\"mv-scroll\"><table class=\"mv-table\">\n      <thead><tr><th>Слова</th><th>Форма</th><th>Примечание</th></tr></thead>\n      <tbody>\n        <tr><td>roof, belief, chief, cliff, proof, safe, chef, reef</td><td>roofs, beliefs, chiefs, cliffs, proofs, safes, chefs, reefs</td><td>f не меняется на v</td></tr>\n        <tr><td>scarf, dwarf, hoof, handkerchief</td><td>scarves / scarfs, dwarfs / dwarves, hooves / hoofs, handkerchiefs / handkerchieves</td><td>оба варианта</td></tr>\n        <tr><td>mosquito, volcano, tornado, zero</td><td>mosquitoes / mosquitos, volcanoes / volcanos, tornadoes / tornados, zeros / zeroes</td><td>оба варианта</td></tr>\n        <tr><td>avocado, memo, logo</td><td>avocados, memos, logos</td><td>только + s</td></tr>\n        <tr><td>stomach, monarch, epoch</td><td>stomachs, monarchs, epochs</td><td>ch = /k/, значит + s</td></tr>\n        <tr><td>German, Roman, human, Norman</td><td>Germans, Romans, humans, Normans</td><td>не -men</td></tr>\n        <tr><td>policeman, fireman, postman</td><td>policemen, firemen, postmen</td><td>-man → -men</td></tr>\n      </tbody>\n    </table></div>\n    <div class=\"mv-note\">Для слов на -o и -f ориентируйтесь на список и словарь: закономерности есть, исключений много. Принимаются все формы, которые словарь признаёт стандартными.</div>\n  </details>\n</section>\n\n<!-- 5 -->\n<section class=\"mv-sec\" id=\"nr-5\">\n  <span id=\"неправильное-множественное-число\"></span>\n  <h2><span class=\"mv-num\">5</span>Особые формы числа</h2>\n  <p class=\"mv-lead\">Неправильные формы, слова без изменений и слова только в одном числе.</p>\n\n  <h3 class=\"nr-h3\"><span id=\"смена-гласной-или-добавление-en\"></span>Смена гласной или -en</h3>\n  <div class=\"nr-chipgrid\">\n    <div class=\"nr-pill\"><b>man</b><i>→</i><span>men</span></div>\n    <div class=\"nr-pill\"><b>woman</b><i>→</i><span>women</span></div>\n    <div class=\"nr-pill\"><b>foot</b><i>→</i><span>feet</span></div>\n    <div class=\"nr-pill\"><b>tooth</b><i>→</i><span>teeth</span></div>\n    <div class=\"nr-pill\"><b>goose</b><i>→</i><span>geese</span></div>\n    <div class=\"nr-pill\"><b>mouse</b><i>→</i><span>mice</span></div>\n    <div class=\"nr-pill\"><b>child</b><i>→</i><span>children</span></div>\n    <div class=\"nr-pill\"><b>ox</b><i>→</i><span>oxen</span></div>\n    <div class=\"nr-pill\"><b>person</b><i>→</i><span>people</span></div>\n  </div>\n  <div class=\"mv-note\"><span class=\"mv-m\">people</span> — обычное мн. число от person: one person, two people. <i>Persons</i> — официальные тексты. <i>A people</i> (народ) → <i>peoples</i>.</div>\n\n  <h3 class=\"nr-h3\"><span id=\"одна-форма-для-обоих-чисел\"></span>Одна форма для обоих чисел</h3>\n  <div class=\"mv-scroll\"><table class=\"mv-table\">\n    <thead><tr><th>Слова</th><th>Пример</th></tr></thead>\n    <tbody>\n      <tr><td>sheep, deer, moose, bison</td><td>one sheep, two sheep; a deer, many deer</td></tr>\n      <tr><td>fish, salmon, trout, cod</td><td>a fish, five fish; fishes — разные виды</td></tr>\n      <tr><td>species, series, means</td><td>this species, these species</td></tr>\n      <tr><td>aircraft, spacecraft, crossroads, headquarters</td><td>one aircraft, ten aircraft; a crossroads, two crossroads</td></tr>\n      <tr><td>Chinese, Japanese, Swiss, Portuguese</td><td>two Chinese, three Swiss</td></tr>\n    </tbody>\n  </table></div>\n\n  <h3 class=\"nr-h3\"><span id=\"заимствованные-формы\"></span>Заимствованные формы</h3>\n  <div class=\"mv-scroll\"><table class=\"mv-table\">\n    <thead><tr><th>Окончание</th><th>Форма</th><th>Примеры</th></tr></thead>\n    <tbody>\n      <tr><td>-is</td><td><span class=\"mv-tag mv-t-pr\">→ -es</span></td><td>analysis → analyses, crisis → crises, thesis → theses, basis → bases</td></tr>\n      <tr><td>-on</td><td><span class=\"mv-tag mv-t-pr\">→ -a</span></td><td>criterion → criteria, phenomenon → phenomena</td></tr>\n      <tr><td>-um</td><td><span class=\"mv-tag mv-t-pr\">→ -a</span></td><td>bacterium → bacteria, curriculum → curricula; <i>но</i> museum → museums</td></tr>\n      <tr><td>-us</td><td><span class=\"mv-tag mv-t-pr\">→ -i</span></td><td>stimulus → stimuli, nucleus → nuclei; <i>но</i> bus → buses, virus → viruses</td></tr>\n      <tr><td>-ix, -ex</td><td><span class=\"mv-tag mv-t-pr\">→ -ices</span></td><td>matrix → matrices, appendix → appendices</td></tr>\n    </tbody>\n  </table></div>\n  <details class=\"nr-more\">\n    <summary>Ещё заимствования и data / media</summary>\n    <div class=\"mv-scroll\"><table class=\"mv-table\">\n      <thead><tr><th>Окончание</th><th>Примеры</th></tr></thead>\n      <tbody>\n        <tr><td>-us → -i (ещё)</td><td>alumnus → alumni, radius → radii / radiuses, syllabus → syllabuses / syllabi, cactus → cacti / cactuses, fungus → fungi / funguses</td></tr>\n        <tr><td>-a → -ae</td><td>larva → larvae, alga → algae, formula → formulae / formulas, antenna → antennae / antennas</td></tr>\n        <tr><td>-ix, -ex (ещё)</td><td>vertex → vertices, index → indexes / indices (книги — indexes, математика — indices)</td></tr>\n        <tr><td>-eau</td><td>bureau → bureaux / bureaus, plateau → plateaus / plateaux</td></tr>\n        <tr><td>-is → -es (ещё)</td><td>hypothesis → hypotheses, diagnosis → diagnoses, oasis → oases (-es читается /iːz/)</td></tr>\n      </tbody>\n    </table></div>\n    <div class=\"mv-note\"><b>data</b> и <b>media</b>: в повседневной речи и IT — масса (<i>The data is stored safely</i>), в науке часто мн. ч. (<i>The data show a clear trend</i>). Оба варианта допустимы.</div>\n  </details>\n\n  <h3 class=\"nr-h3\"><span id=\"только-единственное-или-только-множественное-число\"></span>Только одно число</h3>\n  <div class=\"mv-pair\">\n    <div id=\"только-единственное-число\"><h4><span class=\"mv-tag mv-t-ad\">Только ед. число</span></h4>\n      <p class=\"nr-p\">mathematics, physics, economics, politics, news, measles, darts</p>\n      <span class=\"mv-ex\">Physics <span class=\"mv-m\">is</span> difficult. The news <span class=\"mv-m\">is</span> good.</span>\n      <span class=\"mv-ex\">Ten pounds <span class=\"mv-m\">is</span> a lot. Three weeks <span class=\"mv-m\">is</span> a long time.</span></div>\n    <div id=\"только-множественное-число\"><h4><span class=\"mv-tag mv-t-du\">Только мн. число</span></h4>\n      <p class=\"nr-p\">scissors, trousers, jeans, glasses, clothes, stairs, savings, thanks, police, cattle</p>\n      <span class=\"mv-ex\">My glasses <span class=\"mv-m\">are</span> on the table.</span>\n      <span class=\"mv-ex\">The police <span class=\"mv-m\">are</span> coming.</span></div>\n  </div>\n  <div class=\"mv-note\">Парные вещи считаем через <span class=\"mv-m\">a pair of</span>: <span class=\"mv-ok\">a pair of scissors</span>, <span class=\"mv-ok\">two pairs of trousers</span>, <span class=\"mv-x\">a scissor</span>.</div>\n  <details class=\"nr-more\">\n    <summary>Слова с двумя ролями и полные списки</summary>\n    <div class=\"mv-scroll\"><table class=\"mv-table\">\n      <thead><tr><th>Слово</th><th>Особенность</th></tr></thead>\n      <tbody>\n        <tr><td>statistics</td><td>наука — ед.: <i>Statistics is a hard subject</i>; цифры — мн.: <i>The statistics are alarming</i></td></tr>\n        <tr><td>politics</td><td><i>Politics is interesting</i>; взгляды — мн.: <i>Her politics are liberal</i></td></tr>\n        <tr><td>economics</td><td>наука — ед.; экономика проекта — мн.: <i>the economics of the project are unclear</i></td></tr>\n        <tr><td>series, species, means</td><td>форма одна, глагол по смыслу: <i>This species is rare. These species are rare.</i></td></tr>\n        <tr><td>headquarters</td><td>любой глагол: <i>The headquarters is / are in Leeds.</i></td></tr>\n        <tr><td>police, people, cattle, clergy</td><td>всегда мн. ч. Один человек — a police officer, a policeman</td></tr>\n      </tbody>\n    </table></div>\n    <div class=\"mv-scroll\"><table class=\"mv-table\">\n      <thead><tr><th>Группа (только мн.)</th><th>Слова</th></tr></thead>\n      <tbody>\n        <tr><td>Парные предметы</td><td>scissors, trousers, jeans, shorts, glasses, binoculars, pyjamas, tights, pliers, tweezers, scales</td></tr>\n        <tr><td>Одежда и вещи</td><td>clothes, belongings, goods, surroundings</td></tr>\n        <tr><td>Места</td><td>stairs, outskirts, premises, the Alps</td></tr>\n        <tr><td>Деньги, вежливость</td><td>savings, earnings, thanks, congratulations, regards</td></tr>\n        <tr><td>Прочее</td><td>contents, remains, manners, customs, arms, police, cattle, clergy</td></tr>\n      </tbody>\n    </table></div>\n    <div class=\"mv-scroll\"><table class=\"mv-table\">\n      <thead><tr><th>Группа (только ед.)</th><th>Слова</th></tr></thead>\n      <tbody>\n        <tr><td>Науки, деятельность</td><td>mathematics, physics, economics, politics, athletics, gymnastics, linguistics</td></tr>\n        <tr><td>Болезни</td><td>measles, mumps, diabetes</td></tr>\n        <tr><td>Игры</td><td>darts, billiards, dominoes, draughts</td></tr>\n        <tr><td>Неисчисляемые</td><td>information, advice, furniture, luggage, money, progress, weather</td></tr>\n      </tbody>\n    </table></div>\n  </details>\n</section>\n\n<!-- 6 -->\n<section class=\"mv-sec\" id=\"nr-6\">\n  <span id=\"притяжательный-падеж-s-и-of\"></span>\n  <h2><span class=\"mv-num\">6</span>Принадлежность: ’s и of</h2>\n  <p class=\"mv-lead\">Сначала решите, кому принадлежит: человеку, времени, месту — ’s. Предмету — of.</p>\n  <div class=\"mv-scroll\"><table class=\"mv-table\">\n    <thead><tr><th>Образец</th><th>Правило</th><th>Пример</th></tr></thead>\n    <tbody>\n      <tr><td>ед. число</td><td><span class=\"mv-tag mv-t-ab\">+ ’s</span></td><td>the girl’s bag, John’s car, a child’s toy</td></tr>\n      <tr><td>мн. на -s</td><td><span class=\"mv-tag mv-t-ad\">+ ’</span></td><td>the girls’ bags, my parents’ house</td></tr>\n      <tr><td>мн. без -s</td><td><span class=\"mv-tag mv-t-ab\">+ ’s</span></td><td>the children’s room, the men’s coats</td></tr>\n      <tr><td>имя на -s</td><td><span class=\"mv-tag mv-t-of\">’s или ’</span></td><td>James’s book / James’ book</td></tr>\n      <tr><td>семья</td><td><span class=\"mv-tag mv-t-pr\">the + -s + ’</span></td><td>the Smiths’ house</td></tr>\n      <tr><td>составное</td><td><span class=\"mv-tag mv-t-ab\">’s на последнем</span></td><td>my sister-in-law’s car</td></tr>\n      <tr><td>местоимения</td><td><span class=\"mv-tag mv-t-du\">без апострофа</span></td><td>its, hers, ours, yours, theirs</td></tr>\n    </tbody>\n  </table></div>\n  <div class=\"mv-grid\">\n    <div class=\"mv-card\"><b class=\"mv-ic\">🧑</b><h4>’s</h4><p>люди, животные, время, организации, места</p><span class=\"mv-ex\">the teacher’s desk, a week’s holiday, London’s museums</span></div>\n    <div class=\"mv-card\"><b class=\"mv-ic\">🚪</b><h4>of</h4><p>предметы, части целого, названия</p><span class=\"mv-ex\">the door of the room, the top of the mountain</span></div>\n    <div class=\"mv-card\"><b class=\"mv-ic\">🎒</b><h4>noun + noun</h4><p>класс, назначение</p><span class=\"mv-ex\">a school bag, <span class=\"mv-x\">a school’s bag</span></span></div>\n    <div class=\"mv-card\"><b class=\"mv-ic\">🏪</b><h4>’s без слова</h4><p>магазин, дом, врач</p><span class=\"mv-ex\">at the dentist’s, at Anna’s</span></div>\n  </div>\n  <div class=\"mv-note\"><span class=\"mv-m\">it’s</span> = it is / it has. <span class=\"mv-m\">its</span> — притяжательное, без апострофа: <i>The dog wagged its tail.</i></div>\n  <h3 class=\"nr-h3\">Выберите форму</h3>\n  <div class=\"nr-quiz\" data-title=\"poss\">\n    <div class=\"nr-q\"><span class=\"nr-qs\">the bag of the girl →</span><div class=\"nr-opts\"><button type=\"button\" data-ok=\"1\">the girl’s bag</button><button type=\"button\">the girls bag</button><button type=\"button\">the girl bag</button></div></div>\n    <div class=\"nr-q\"><span class=\"nr-qs\">the door … the room</span><div class=\"nr-opts\"><button type=\"button\">the room’s door</button><button type=\"button\" data-ok=\"1\">the door of the room</button><button type=\"button\">the rooms door</button></div></div>\n    <div class=\"nr-q\"><span class=\"nr-qs\">The dog wagged … tail.</span><div class=\"nr-opts\"><button type=\"button\">it’s</button><button type=\"button\" data-ok=\"1\">its</button><button type=\"button\">its’</button></div></div>\n    <div class=\"nr-q\"><span class=\"nr-qs\">a friend … (мой)</span><div class=\"nr-opts\"><button type=\"button\">a my friend</button><button type=\"button\" data-ok=\"1\">a friend of mine</button><button type=\"button\">a friend of me</button></div></div>\n  </div>\n  <details class=\"nr-more\" id=\"двойной-родительный\">\n    <summary>Двойной родительный и совместное владение</summary>\n    <div class=\"mv-scroll\"><table class=\"mv-table\">\n      <thead><tr><th>Модель</th><th>Пример</th></tr></thead>\n      <tbody>\n        <tr><td>a / this / that / some … of + ’s</td><td>a friend of my father’s</td></tr>\n        <tr><td>a / this / that … of + местоимение</td><td>a friend of mine, that car of his</td></tr>\n        <tr><td>a / this … of + имя + ’s</td><td>an old school friend of John’s</td></tr>\n      </tbody>\n    </table></div>\n    <p class=\"nr-p\">Когда перед существительным уже стоит a, this, that, some: <span class=\"mv-x\">a my friend</span> → <span class=\"mv-ok\">a friend of mine</span>.</p>\n    <div class=\"mv-scroll\" id=\"совместное-владение\"><table class=\"mv-table\">\n      <thead><tr><th>Ситуация</th><th>Конструкция</th><th>Пример</th></tr></thead>\n      <tbody>\n        <tr><td>Общий предмет</td><td>’s у последнего имени</td><td>John and Mary’s house (один дом)</td></tr>\n        <tr><td>Разные предметы</td><td>’s у каждого</td><td>John’s and Mary’s houses (два дома)</td></tr>\n        <tr><td>Устойчивые обороты</td><td>’s</td><td>for goodness’ sake, a day’s work</td></tr>\n      </tbody>\n    </table></div>\n  </details>\n</section>\n\n<!-- 7 -->\n<section class=\"mv-sec\" id=\"nr-7\">\n  <span id=\"составные-существительные-compound-nouns\"></span>\n  <h2><span class=\"mv-num\">7</span>Составные существительные</h2>\n  <p class=\"mv-lead\">Главное слово получает -s. Если существительного внутри нет, -s в конце.</p>\n  <div class=\"mv-scroll\"><table class=\"mv-table\">\n    <thead><tr><th>Тип</th><th>Singular</th><th>Plural</th></tr></thead>\n    <tbody>\n      <tr><td>Главное слово последнее</td><td>bedroom, traffic light</td><td>bedrooms, traffic lights</td></tr>\n      <tr><td>Главное слово не последнее</td><td>mother-in-law, passer-by</td><td><span class=\"mv-m\">mothers</span>-in-law, <span class=\"mv-m\">passers</span>-by</td></tr>\n      <tr><td>Нет существительного</td><td>grown-up, take-away</td><td>grown-ups, take-aways</td></tr>\n      <tr><td>Слова на -ful</td><td>spoonful, handful</td><td>spoonfuls, handfuls</td></tr>\n    </tbody>\n  </table></div>\n  <div class=\"mv-note\">Главное слово — то, что называет сам предмет: <i>mother</i>-in-law, значит <i>mothers</i>-in-law, а не <span class=\"mv-x\">mother-in-laws</span>.</div>\n  <details class=\"nr-more\">\n    <summary>Модели составных и ещё примеры</summary>\n    <div class=\"mv-scroll\"><table class=\"mv-table\">\n      <thead><tr><th>Модель</th><th>Примеры</th></tr></thead>\n      <tbody>\n        <tr><td>noun + noun</td><td>bedroom, car door, coffee cup, bus stop</td></tr>\n        <tr><td>adjective + noun</td><td>greenhouse, blackboard, software, fast food</td></tr>\n        <tr><td>verb-ing + noun</td><td>washing machine, swimming pool, driving licence</td></tr>\n        <tr><td>noun + verb(-er)</td><td>sunrise, rainfall, hairdryer</td></tr>\n        <tr><td>preposition + noun</td><td>underwear, input, bystander</td></tr>\n        <tr><td>noun + prep. + noun</td><td>mother-in-law, forget-me-not</td></tr>\n        <tr><td>Ещё мн. ч.</td><td>lookers-on, runners-up, commanders-in-chief, courts-martial, attorneys general</td></tr>\n      </tbody>\n    </table></div>\n    <p class=\"nr-p\">Написание закреплено словарём: слитно (toothbrush), через дефис (mother-in-law) или раздельно (traffic light). Ударение обычно на первой части.</p>\n  </details>\n\n  <h3 class=\"nr-h3\" id=\"существительное-в-роли-определения-noun-noun\">Существительное как определение</h3>\n  <div class=\"mv-scroll\"><table class=\"mv-table\">\n    <thead><tr><th>Правило</th><th>Верно</th><th>Неверно</th></tr></thead>\n    <tbody>\n      <tr><td>Определяющее слово — в ед. числе</td><td><span class=\"mv-ok\">a shoe shop</span></td><td><span class=\"mv-x\">a shoes shop</span></td></tr>\n      <tr><td>Число + единица — ед., через дефис</td><td><span class=\"mv-ok\">a two-hour delay</span></td><td><span class=\"mv-x\">a two-hours delay</span></td></tr>\n      <tr><td>Число + year-old</td><td><span class=\"mv-ok\">a six-year-old girl</span></td><td><span class=\"mv-x\">six-years-old girl</span></td></tr>\n      <tr><td>Неодушевлённое — без ’s</td><td><span class=\"mv-ok\">a car door</span></td><td><span class=\"mv-x\">a car’s door</span></td></tr>\n      <tr><td>Для групп людей — ’s</td><td><span class=\"mv-ok\">a children’s book, a girls’ school</span></td><td></td></tr>\n    </tbody>\n  </table></div>\n  <details class=\"nr-more\">\n    <summary>Когда определение стоит во мн. числе</summary>\n    <div class=\"mv-scroll\"><table class=\"mv-table\">\n      <thead><tr><th>Случай</th><th>Пример</th></tr></thead>\n      <tbody>\n        <tr><td>Постоянно во мн. ч.</td><td>a clothes shop, a goods train, a glasses case</td></tr>\n        <tr><td>Устойчивое сочетание с -s</td><td>a sports car, a savings account, a customs officer, an arms race, a sales manager, a careers adviser</td></tr>\n        <tr><td>news</td><td>a news agency, a news bulletin</td></tr>\n        <tr><td>noun + noun или noun + of + noun</td><td>a wine glass (для вина) — a glass of wine (с вином)</td></tr>\n      </tbody>\n    </table></div>\n  </details>\n</section>\n\n<!-- 8 -->\n<section class=\"mv-sec\" id=\"nr-8\">\n  <span id=\"собирательные-существительные-collective-nouns\"></span>\n  <h2><span class=\"mv-num\">8</span>Группы людей: team, family, staff</h2>\n  <p class=\"mv-lead\">team, family, staff, government, committee, company, audience, class, crew, jury, crowd. Глагол зависит от того, что вы подчёркиваете.</p>\n  <div class=\"mv-pair\">\n    <div><h4>Группа как целое → ед. ч.</h4><span class=\"mv-ex\">The team <span class=\"mv-m\">is</span> playing well.</span><span class=\"mv-ex\">The government <span class=\"mv-m\">has</span> decided.</span></div>\n    <div><h4>Люди внутри → мн. ч.</h4><span class=\"mv-ex\">The staff <span class=\"mv-m\">were</span> very helpful.</span><span class=\"mv-ex\">Liverpool <span class=\"mv-m\">are</span> winning.</span></div>\n  </div>\n  <div class=\"mv-scroll\"><table class=\"mv-table\">\n    <thead><tr><th>Модель</th><th>Глагол</th><th>Пример</th></tr></thead>\n    <tbody>\n      <tr><td>the police, cattle, clergy</td><td><span class=\"mv-tag mv-t-du\">всегда мн.</span></td><td>The police are here.</td></tr>\n      <tr><td>the + прилагательное</td><td><span class=\"mv-tag mv-t-du\">мн.</span></td><td>The rich are not always happy.</td></tr>\n      <tr><td>a number of + мн.</td><td><span class=\"mv-tag mv-t-du\">мн.</span></td><td>A number of students are absent.</td></tr>\n      <tr><td>the number of + мн.</td><td><span class=\"mv-tag mv-t-ad\">ед.</span></td><td>The number of students is growing.</td></tr>\n      <tr><td>each / every / either / neither</td><td><span class=\"mv-tag mv-t-ad\">ед.</span></td><td>Every student has a book.</td></tr>\n      <tr><td>a lot of / plenty of</td><td><span class=\"mv-tag mv-t-of\">по существительному</span></td><td>A lot of money is wasted. A lot of people are waiting.</td></tr>\n    </tbody>\n  </table></div>\n  <div class=\"mv-note\"><b>British и American.</b> Британский английский допускает оба числа (<i>The committee has / have decided</i>), американский обычно выбирает единственное. Согласуйте и местоимения: <span class=\"mv-m\">its</span> — с целым, <span class=\"mv-m\">their</span> — с людьми.</div>\n</section>\n\n<!-- 9 -->\n<section class=\"mv-sec\" id=\"nr-9\">\n  <span id=\"артикли-и-определители-с-существительными\"></span>\n  <h2><span class=\"mv-num\">9</span>Артикли: a, the или ничего</h2>\n  <p class=\"mv-lead\">Сначала тип слова, потом ситуация: первое упоминание, известное, общее.</p>\n  <div class=\"mv-scroll\"><table class=\"mv-table\">\n    <thead><tr><th>Ситуация</th><th>Countable sg.</th><th>Countable pl.</th><th>Uncountable</th></tr></thead>\n    <tbody>\n      <tr><td>Первое упоминание</td><td><span class=\"mv-m\">a</span> book</td><td>(some) books</td><td>(some) water</td></tr>\n      <tr><td>Известное, конкретное</td><td><span class=\"mv-m\">the</span> book</td><td><span class=\"mv-m\">the</span> books</td><td><span class=\"mv-m\">the</span> water</td></tr>\n      <tr><td>Обобщение</td><td>A dog is friendly.</td><td>Dogs are friendly.</td><td>Water is essential.</td></tr>\n    </tbody>\n  </table></div>\n  <div class=\"mv-grid\">\n    <div class=\"mv-card\" id=\"a-an\"><b class=\"mv-ic\">🅰️</b><h4>a / an</h4><p>по <b>звуку</b>, не по букве. Один из многих, профессия, «в час / в неделю».</p><span class=\"mv-ex\">a university, an hour</span><span class=\"mv-ex\">She is a teacher. Twice a week.</span></div>\n    <div class=\"mv-card\" id=\"the\"><b class=\"mv-ic\">👆</b><h4>the</h4><p>Уже упомянуто, понятно из ситуации, единственное в своём роде, превосходная степень.</p><span class=\"mv-ex\">the sun, the best student, the Thames</span></div>\n    <div class=\"mv-card\" id=\"нулевой-артикль\"><b class=\"mv-ic\">∅</b><h4>Без артикля</h4><p>Общее значение, еда, языки, большинство стран и городов, дни, месяцы.</p><span class=\"mv-ex\">Music helps. have breakfast. in July</span></div>\n  </div>\n  <h3 class=\"nr-h3\">Выберите артикль</h3>\n  <div class=\"nr-quiz\" data-title=\"art\">\n    <div class=\"nr-q\"><span class=\"nr-qs\">She is … honest teacher.</span><div class=\"nr-opts\"><button type=\"button\">a</button><button type=\"button\" data-ok=\"1\">an</button><button type=\"button\">the</button></div></div>\n    <div class=\"nr-q\"><span class=\"nr-qs\">I bought a book. … book was boring.</span><div class=\"nr-opts\"><button type=\"button\">A</button><button type=\"button\" data-ok=\"1\">The</button><button type=\"button\">—</button></div></div>\n    <div class=\"nr-q\"><span class=\"nr-qs\">… music helps people relax.</span><div class=\"nr-opts\"><button type=\"button\">The</button><button type=\"button\">A</button><button type=\"button\" data-ok=\"1\">— (без артикля)</button></div></div>\n    <div class=\"nr-q\"><span class=\"nr-qs\">She plays … piano.</span><div class=\"nr-opts\"><button type=\"button\" data-ok=\"1\">the</button><button type=\"button\">a</button><button type=\"button\">—</button></div></div>\n  </div>\n  <details class=\"nr-more\">\n    <summary>a / an: все случаи</summary>\n    <div class=\"mv-scroll\"><table class=\"mv-table\">\n      <thead><tr><th>Случай</th><th>Пример</th></tr></thead>\n      <tbody>\n        <tr><td>Выбор по звуку</td><td>a university, a European, a one-way street, a useful book</td></tr>\n        <tr><td>Гласный звук</td><td>an hour, an honest man, an MP, an X-ray, an SOS, an 18-year-old</td></tr>\n        <tr><td>Первое упоминание</td><td>I saw a dog.</td></tr>\n        <tr><td>Профессия, класс</td><td>She is a teacher. He works as a taxi driver.</td></tr>\n        <tr><td>Частота, цена, скорость</td><td>twice a week, £5 a kilo, sixty miles an hour</td></tr>\n        <tr><td>Восклицание, такой</td><td>What a day! such a long day, quite a surprise</td></tr>\n        <tr><td>Дробь, число</td><td>half an hour, half a kilo, a hundred</td></tr>\n        <tr><td>Один из многих</td><td>a friend of mine</td></tr>\n      </tbody>\n    </table></div>\n  </details>\n  <details class=\"nr-more\">\n    <summary>the: все случаи</summary>\n    <div class=\"mv-scroll\"><table class=\"mv-table\">\n      <thead><tr><th>Ситуация</th><th>Пример</th></tr></thead>\n      <tbody>\n        <tr><td>Уже упомянуто</td><td>I bought a book. The book was boring.</td></tr>\n        <tr><td>Понятно из ситуации</td><td>Open the window, please.</td></tr>\n        <tr><td>Единственный в своём роде</td><td>the sun, the moon, the world, the sky, the internet</td></tr>\n        <tr><td>Превосходная степень, first, last, only, same</td><td>the best student, the first day, the only way</td></tr>\n        <tr><td>the + прилагательное</td><td>the rich, the poor, the elderly</td></tr>\n        <tr><td>Реки, моря, океаны, горные цепи, пустыни, группы островов</td><td>the Thames, the Atlantic, the Alps, the Sahara, the Canaries</td></tr>\n        <tr><td>Страны мн. ч. или с republic, kingdom, states</td><td>the Netherlands, the Philippines, the UK, the USA</td></tr>\n        <tr><td>Инструменты, кино, театр, радио</td><td>play the piano, go to the cinema, listen to the radio</td></tr>\n        <tr><td>Семья</td><td>the Smiths</td></tr>\n        <tr><td>Названия на the</td><td>the Eiffel Tower, the White House, the British Museum</td></tr>\n      </tbody>\n    </table></div>\n  </details>\n  <details class=\"nr-more\">\n    <summary>Без артикля: все случаи</summary>\n    <div class=\"mv-scroll\"><table class=\"mv-table\">\n      <thead><tr><th>Ситуация</th><th>Пример</th></tr></thead>\n      <tbody>\n        <tr><td>Неисчисляемое, общий смысл</td><td>Music helps people relax. Water is essential.</td></tr>\n        <tr><td>Мн. число, общий смысл</td><td>Children need sleep.</td></tr>\n        <tr><td>Приёмы пищи</td><td>have breakfast, after lunch</td></tr>\n        <tr><td>Языки</td><td>speak English, learn French</td></tr>\n        <tr><td>Страны, города, улицы, континенты</td><td>in France, in Paris, Oxford Street, Asia</td></tr>\n        <tr><td>Вершины, озёра, отдельные острова</td><td>Mount Everest, Lake Windermere, Bali</td></tr>\n        <tr><td>Названия с именем</td><td>Buckingham Palace, Heathrow Airport, Harvard University</td></tr>\n        <tr><td>Спорт, игры, школьные предметы</td><td>play football, play chess, study history</td></tr>\n        <tr><td>Транспорт после by</td><td>by bus, by train, on foot</td></tr>\n        <tr><td>Дни, месяцы, времена года</td><td>on Monday, in July, in winter</td></tr>\n        <tr><td>Звание + имя</td><td>Doctor Brown, President Lincoln</td></tr>\n        <tr><td>Устойчивые места (цель визита)</td><td>at school, in hospital, in prison, at university, in bed, at work, at home</td></tr>\n      </tbody>\n    </table></div>\n    <div class=\"mv-note\"><i>She is in hospital</i> — лечится. <i>She went to the hospital to visit a friend</i> — здание. Так же: <i>at school</i> — учится, <i>at the school</i> — в здании школы.</div>\n  </details>\n</section>\n\n<!-- 10 -->\n<section class=\"mv-sec\" id=\"nr-10\">\n  <span id=\"количественные-определители-quantifiers\"></span>\n  <h2><span class=\"mv-num\">10</span>many, much, few, little</h2>\n  <p class=\"mv-lead\">Выбор зависит от типа слова: исчисляемое или неисчисляемое.</p>\n  <div class=\"mv-scroll\"><table class=\"mv-table\">\n    <thead><tr><th>Определитель</th><th><span class=\"mv-tag mv-t-ab\">Countable</span></th><th><span class=\"mv-tag mv-t-ad\">Uncountable</span></th></tr></thead>\n    <tbody>\n      <tr><td>много</td><td>many books</td><td>much time</td></tr>\n      <tr><td>немного (достаточно)</td><td>a few friends</td><td>a little money</td></tr>\n      <tr><td>почти нет</td><td>few chances</td><td>little hope</td></tr>\n      <tr><td>меньше</td><td>fewer mistakes</td><td>less noise</td></tr>\n      <tr><td>a lot of · plenty of · enough</td><td>✓ a lot of books</td><td>✓ a lot of water</td></tr>\n      <tr><td>some · any · no</td><td>✓ some apples</td><td>✓ any water</td></tr>\n      <tr><td>every · each</td><td>✓ ед. ч.: every student</td><td>—</td></tr>\n    </tbody>\n  </table></div>\n  <div class=\"mv-pair\">\n    <div><h4><span class=\"mv-tag mv-t-ab\">a few / a little</span></h4><span class=\"mv-ex\">I have <span class=\"mv-m\">a few</span> ideas. — немного, хватит</span></div>\n    <div><h4><span class=\"mv-tag mv-t-du\">few / little</span></h4><span class=\"mv-ex\">I have <span class=\"mv-m\">few</span> ideas. — почти нет</span></div>\n  </div>\n  <h3 class=\"nr-h3\">Выберите слово</h3>\n  <div class=\"nr-quiz\" data-title=\"quant\">\n    <div class=\"nr-q\"><span class=\"nr-qs\">There isn’t … time.</span><div class=\"nr-opts\"><button type=\"button\">many</button><button type=\"button\" data-ok=\"1\">much</button><button type=\"button\">few</button></div></div>\n    <div class=\"nr-q\"><span class=\"nr-qs\">She has … friends here.</span><div class=\"nr-opts\"><button type=\"button\" data-ok=\"1\">a few</button><button type=\"button\">a little</button><button type=\"button\">much</button></div></div>\n    <div class=\"nr-q\"><span class=\"nr-qs\">We made … mistakes this time.</span><div class=\"nr-opts\"><button type=\"button\" data-ok=\"1\">fewer</button><button type=\"button\">less</button><button type=\"button\">little</button></div></div>\n    <div class=\"nr-q\"><span class=\"nr-qs\">There is … noise in the street.</span><div class=\"nr-opts\"><button type=\"button\">fewer</button><button type=\"button\" data-ok=\"1\">less</button><button type=\"button\">many</button></div></div>\n  </div>\n  <details class=\"nr-more\">\n    <summary>Остальные определители и правила употребления</summary>\n    <div class=\"mv-scroll\"><table class=\"mv-table\">\n      <thead><tr><th>Определитель</th><th>Countable</th><th>Uncountable</th><th>Пример</th></tr></thead>\n      <tbody>\n        <tr><td>a number of / several / a couple of</td><td>да</td><td>нет</td><td>several students</td></tr>\n        <tr><td>a great deal of / a large amount of</td><td>нет</td><td>да</td><td>a great deal of work</td></tr>\n        <tr><td>both</td><td>да, два предмета</td><td>нет</td><td>both parents</td></tr>\n        <tr><td>most / all</td><td>да, мн. ч.</td><td>да</td><td>most people, all water</td></tr>\n      </tbody>\n    </table></div>\n    <div class=\"mv-scroll\"><table class=\"mv-table\">\n      <thead><tr><th>Конструкция</th><th>Правило</th><th>Пример</th></tr></thead>\n      <tbody>\n        <tr><td>much, many</td><td>вопросы и отрицания</td><td>Do you have much time? I don’t have many friends.</td></tr>\n        <tr><td>a lot of</td><td>утверждения</td><td>I have a lot of time.</td></tr>\n        <tr><td>too much, so many, how much</td><td>допустимы в утверждениях</td><td>There is too much sugar.</td></tr>\n        <tr><td>some</td><td>утверждения, предложения, просьбы</td><td>Would you like some tea?</td></tr>\n        <tr><td>any</td><td>вопросы, отрицания, «любой»</td><td>Do you have any questions? Any student can join.</td></tr>\n        <tr><td>no / not any</td><td>отрицание</td><td>There is no time. There isn’t any time.</td></tr>\n        <tr><td>hundred, thousand, million после числа</td><td>без -s</td><td>three hundred people, two thousand pounds</td></tr>\n        <tr><td>hundreds of, thousands of</td><td>с -s</td><td>hundreds of people</td></tr>\n      </tbody>\n    </table></div>\n    <div class=\"mv-note\"><b>Fewer</b> — для исчисляемого, <b>less</b> — для неисчисляемого. <i>Less than ten minutes</i> и <i>less than 20 items</i> в обычной речи допустимы: сумма, время, расстояние воспринимаются как одно целое.</div>\n  </details>\n</section>\n\n<!-- 11 -->\n<section class=\"mv-sec\" id=\"nr-11\">\n  <span id=\"частые-ошибки\"></span>\n  <h2><span class=\"mv-num\">11</span>Частые ошибки и проверка</h2>\n  <p class=\"mv-lead\">Типичные промахи и короткий список вопросов перед ответом.</p>\n  <div class=\"mv-scroll\"><table class=\"mv-table\">\n    <thead><tr><th>Неправильно</th><th>Правильно</th><th>Почему</th></tr></thead>\n    <tbody>\n      <tr><td><span class=\"mv-x\">an advice</span></td><td><span class=\"mv-ok\">a piece of advice</span></td><td>неисчисляемое</td></tr>\n      <tr><td><span class=\"mv-x\">two informations</span></td><td><span class=\"mv-ok\">two pieces of information</span></td><td>неисчисляемое</td></tr>\n      <tr><td><span class=\"mv-x\">the news are</span></td><td><span class=\"mv-ok\">the news is</span></td><td>ед. число</td></tr>\n      <tr><td><span class=\"mv-x\">childs, mans</span></td><td><span class=\"mv-ok\">children, men</span></td><td>особая форма</td></tr>\n      <tr><td><span class=\"mv-x\">a scissor</span></td><td><span class=\"mv-ok\">a pair of scissors</span></td><td>только мн. ч.</td></tr>\n      <tr><td><span class=\"mv-x\">the police is</span></td><td><span class=\"mv-ok\">the police are</span></td><td>всегда мн. ч.</td></tr>\n      <tr><td><span class=\"mv-x\">much books</span></td><td><span class=\"mv-ok\">many books</span></td><td>much — с неисчисляемым</td></tr>\n      <tr><td><span class=\"mv-x\">a two-hours journey</span></td><td><span class=\"mv-ok\">a two-hour journey</span></td><td>определение — в ед. ч.</td></tr>\n      <tr><td><span class=\"mv-x\">Johns car</span></td><td><span class=\"mv-ok\">John’s car</span></td><td>нужен апостроф</td></tr>\n      <tr><td><span class=\"mv-x\">it’s tail</span></td><td><span class=\"mv-ok\">its tail</span></td><td>притяжательное без апострофа</td></tr>\n      <tr><td><span class=\"mv-x\">a long hair</span></td><td><span class=\"mv-ok\">long hair</span></td><td>волосы — масса</td></tr>\n      <tr><td><span class=\"mv-x\">two mother-in-laws</span></td><td><span class=\"mv-ok\">two mothers-in-law</span></td><td>-s у главного слова</td></tr>\n    </tbody>\n  </table></div>\n  <details class=\"nr-more\" id=\"проверка-перед-ответом\" open>\n    <summary>Проверка перед ответом</summary>\n    <ol class=\"nr-steps\">\n      <li><b>Тип слова</b> — исчисляемое, неисчисляемое или два значения?</li>\n      <li><b>Число</b> — -s, особая форма или слово не меняется?</li>\n      <li><b>Орфография</b> — -es, -ies, -ves, -os / -oes, заимствованные формы.</li>\n      <li><b>Глагол</b> — по форме (news) или по смыслу (the team is); police — мн. ч.</li>\n      <li><b>Мера</b> — для неисчисляемого партитив: a piece of advice.</li>\n      <li><b>Принадлежность</b> — ’s для людей, времени, мест; of для предметов.</li>\n      <li><b>Артикль</b> — a/an по звуку, the при определённости, без артикля при общем смысле.</li>\n      <li><b>Определитель</b> — many / much, few / little, fewer / less.</li>\n    </ol>\n    <div class=\"mv-note\">В упражнении следуйте инструкции: иногда нужна форма слова, иногда сочетание целиком. Уже напечатанные слова не повторяйте. Если допустимы два варианта (James’s и James’), принимаются оба.</div>\n  </details>\n  <details class=\"nr-more\" id=\"род-и-нейтральность\">\n    <summary>Род и нейтральность</summary>\n    <div class=\"mv-scroll\"><table class=\"mv-table\">\n      <thead><tr><th>Что называем</th><th>Как</th><th>Пример</th></tr></thead>\n      <tbody>\n        <tr><td>Профессия, родство (нейтрально)</td><td>одно слово для всех</td><td>teacher, doctor, student, friend, neighbour</td></tr>\n        <tr><td>Парные формы</td><td>-ess, -ine или разные слова</td><td>actor / actress, hero / heroine, prince / princess</td></tr>\n        <tr><td>Современные нейтральные</td><td>вместо слов на -man</td><td>police officer, firefighter, chair, flight attendant</td></tr>\n        <tr><td>Животные</td><td>пары или нейтральное слово</td><td>a bull / a cow, a cock / a hen, an animal</td></tr>\n      </tbody>\n    </table></div>\n    <p class=\"nr-p\">Грамматического рода у существительных нет: он проявляется только в местоимениях he, she, it.</p>\n  </details>\n</section>\n\n</div>";
function nounsRuleHtml(prefix='') {
  const safePrefix=String(prefix).replace(/[^a-zA-Z0-9_-]/g,'');
  return NOUNS_RULE_CONTENT
    .replace(/id="([^"]+)"/g,(_,id)=>'id="'+safePrefix+id+'" data-nouns-id="'+id+'"')
    .replace(/href="#(nr-[^"]+)"/g,(_,id)=>'href="#theory/nouns/'+id+'" data-nouns-anchor="'+id+'"');
}
function revealNounsAnchor(container,anchor) {
  const root=container?.matches?.('.nr')?container:container?.querySelector?.('.nr');
  if(!root)return;
  const id=String(anchor||'').replace(/^#?(?:theory\/nouns\/)?/,'');
  if(!id)return;
  const target=[root,...root.querySelectorAll('[data-nouns-id]')].find(node=>node.dataset.nounsId===id||node.id===id);
  if(!target)return;
  for(let node=target.closest('details');node;node=node.parentElement?.closest('details'))node.open=true;
  const spot=target.closest('details')||target.closest('h3')||target.closest('.mv-sec')||target;
  const scrollArea=root.closest('.reference-reader,.rule-dialog-content');
  if(scrollArea){
    const nav=root.querySelector('.mv-nav');
    scrollArea.scrollTop+=spot.getBoundingClientRect().top-scrollArea.getBoundingClientRect().top-(nav?.getBoundingClientRect().height||0)-16;
  }else spot.scrollIntoView({block:'start',behavior:'instant'});
}
function initialiseNounsRule(container) {
  const root=container?.matches?.('.nr')?container:container?.querySelector?.('.nr');
  if(!root||root.dataset.initialised)return;
  root.dataset.initialised='true';
  root.querySelectorAll('.mv-scroll').forEach((table,index)=>{
    table.tabIndex=0;table.setAttribute('role','region');
    table.setAttribute('aria-label',(table.closest('.mv-sec')?.querySelector('h2')?.textContent||'Таблица правила').trim()+' · таблица '+(index+1));
  });
  root.querySelectorAll('.mv-table').forEach(table=>{
    const heads=[...table.querySelectorAll('thead th')].map(th=>th.textContent.trim());
    table.querySelectorAll('tbody tr').forEach(row=>[...row.children].forEach((cell,i)=>cell.setAttribute('data-label',heads[i]||'')));
  });
  root.addEventListener('click',event=>{
    const link=event.target.closest?.('[data-nouns-anchor]');
    if(link&&root.contains(link)&&event.button===0&&!event.metaKey&&!event.ctrlKey&&!event.altKey&&!event.shiftKey){
      event.preventDefault();event.stopPropagation();
      revealNounsAnchor(root,link.dataset.nounsAnchor);return;
    }
    const word=event.target.closest?.('.nr-words button');
    if(word&&root.contains(word)){
      const box=word.closest('.mv-sec').querySelector('.nr-verdict');
      word.parentElement.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===word)));
      const countable=word.dataset.k==='c';
      box.hidden=false;box.className='nr-verdict '+(countable?'nr-v-c':'nr-v-u');
      box.replaceChildren();
      const title=document.createElement('b');title.textContent=word.textContent+' — '+(countable?'исчисляемое':'неисчисляемое');
      const good=document.createElement('span');good.className='mv-ok';good.textContent=word.dataset.ok;
      const bad=document.createElement('span');bad.className='mv-x';bad.textContent=word.dataset.bad;
      box.append(title,good,bad);return;
    }
    const option=event.target.closest?.('.nr-opts button');
    if(option&&root.contains(option)){
      const question=option.closest('.nr-q');
      if(question.dataset.done)return;
      question.dataset.done='1';
      const right=option.hasAttribute('data-ok');
      question.querySelectorAll('.nr-opts button').forEach(b=>{b.disabled=true;if(b.hasAttribute('data-ok'))b.classList.add('nr-right');});
      if(!right)option.classList.add('nr-wrong');
      question.classList.add(right?'nr-q-ok':'nr-q-bad');
      const quiz=question.closest('.nr-quiz');
      const all=quiz.querySelectorAll('.nr-q'),done=quiz.querySelectorAll('.nr-q[data-done]');
      if(all.length===done.length){
        const score=quiz.querySelectorAll('.nr-q-ok').length;
        let foot=quiz.querySelector('.nr-score');
        if(!foot){foot=document.createElement('div');foot.className='nr-score';quiz.append(foot);}
        foot.replaceChildren();
        const text=document.createElement('span');text.textContent='Результат: '+score+' из '+all.length;
        const again=document.createElement('button');again.type='button';again.className='nr-again';again.textContent='Ещё раз';
        foot.append(text,again);
      }
      return;
    }
    const again=event.target.closest?.('.nr-again');
    if(again&&root.contains(again)){
      const quiz=again.closest('.nr-quiz');
      quiz.querySelectorAll('.nr-q').forEach(q=>{delete q.dataset.done;q.classList.remove('nr-q-ok','nr-q-bad');q.querySelectorAll('button').forEach(b=>{b.disabled=false;b.classList.remove('nr-right','nr-wrong');});});
      quiz.querySelector('.nr-score')?.remove();
    }
  });
}
